INSERT INTO `contents` (`id`, `asset_id`, `author_id`, `main_category_id`, `subcategory_id`, `title`, `slug`, `description`, `preview_image`, `watermarked_preview_image`, `watermarked_preview_video`, `thumbnail_url`, `preview_600_url`, `preview_1200_url`, `author_preview_url`, `content_type`, `is_premium`, `license_type`, `ai_generated`, `width`, `height`, `orientation`, `dominant_color`, `views_count`, `downloads_count`, `likes_count`, `status`, `exclusive_price`, `is_exclusive_sold`, `rejection_reason`, `reviewed_by`, `reviewed_at`, `reviewer_note`, `published_at`, `created_at`, `updated_at`) VALUES
(1, '634839964643', 1, 4, 106, '3 D cartoon headphones question mark and people icons', '3-d-cartoon-headphones-question-mark-and-people-icons', 'A 3D render features a pair of blue and yellow headphones with a gray accent. A green speech bubble containing a white question mark floats near the headphones. Two simplified human figures are depicted: one in blue is positioned near the headphones, and another yellow figure is inside a blue speech bubble. The composition is set against a black background with a white platform beneath the headphones.', 'uploads/contents/1/preview.jpg', 'uploads/contents/1/preview-watermarked.webp', NULL, 'uploads/contents/1/preview-300.webp', 'uploads/contents/1/preview-600.webp', 'uploads/contents/1/preview-1200.webp', 'uploads/contents/1/author-600.webp', 'png', 1, 'premium', 0, 2048, 2048, 'square', NULL, 24, 1, 0, 'published', 250.00, 0, NULL, 1, '2026-07-30 12:06:31', NULL, '2026-07-30 12:06:31', '2026-07-30 05:45:26', '2026-09-10 22:15:51'),
(2, '711518756742', 1, 4, 106, '3 D directional signpost with teal and orange arrows', '3-d-directional-signpost-with-teal-and-orange-arrows', 'Modern 3D directional signpost featuring teal and orange arrows pointing in multiple directions. Clean, realistic wayfinding design isolated on a transparent background, ideal for navigation, maps, UI, branding, infographics, and travel concepts.', 'uploads/contents/2/preview.jpg', 'uploads/contents/2/preview-watermarked.webp', NULL, 'uploads/contents/2/preview-300.webp', 'uploads/contents/2/preview-600.webp', 'uploads/contents/2/preview-1200.webp', 'uploads/contents/2/author-600.webp', 'png', 0, 'free', 0, 2048, 2048, 'square', NULL, 16, 0, 0, 'published', 299.00, 0, NULL, 1, '2026-07-30 12:06:31', NULL, '2026-07-30 12:06:31', '2026-07-30 05:45:39', '2026-09-11 11:12:23'),
(3, '659173946979', 1, 4, 106, '3D Battery Icon with Charging Indicator Power Level on Transparent Background', '3d-battery-icon-with-charging-indicator-power-level-on-transparent-background', 'A 3D rendered battery icon is shown with a charging lightning bolt symbol above it. The battery itself is depicted with a gray casing and a white interior, filled with green bars indicating a high charge level. The bars increase in height from left to right, signifying a full or nearly full battery. The illustration is presented on a white background.', 'uploads/contents/3/preview.jpg', 'uploads/contents/3/preview-watermarked.webp', NULL, 'uploads/contents/3/preview-300.webp', 'uploads/contents/3/preview-600.webp', 'uploads/contents/3/preview-1200.webp', 'uploads/contents/3/author-600.webp', 'png', 0, 'free', 0, 2048, 2048, 'square', NULL, 27, 1, 0, 'published', 350.00, 0, NULL, 1, '2026-07-30 12:06:31', NULL, '2026-07-30 12:06:31', '2026-07-30 05:54:41', '2026-09-11 01:45:02'),
(4, '390134035997', 1, 4, 106, '3D Battery Icon with Leaf and Recycling Symbol for Green Energy Solutions', '3d-battery-icon-with-leaf-and-recycling-symbol-for-green-energy-solutions', 'Eco-friendly 3D battery icon featuring a green leaf and recycling symbol, representing renewable energy, sustainable power, clean technology, battery recycling, environmental protection, and green innovation.', 'uploads/contents/4/preview.jpg', 'uploads/contents/4/preview-watermarked.webp', NULL, 'uploads/contents/4/preview-300.webp', 'uploads/contents/4/preview-600.webp', 'uploads/contents/4/preview-1200.webp', 'uploads/contents/4/author-600.webp', 'png', 0, 'free', 0, 2048, 2048, 'square', NULL, 31, 1, 0, 'published', 489.00, 0, NULL, 1, '2026-07-30 12:06:31', NULL, '2026-07-30 12:06:31', '2026-07-30 05:54:53', '2026-09-11 06:39:42'),
(5, '681270281496', 1, 4, 106, '3D Business Growth and Success Icons for Finance and Investment Concepts', '3d-business-growth-and-success-icons-for-finance-and-investment-concepts', 'A dynamic 3D composition illustrating business growth and success. Green bar charts ascend, topped by a golden trophy. A green arrow curves upwards, symbolizing progress, alongside stacks of coins, a dollar sign, and a briefcase. A target with an arrow in the bullseye represents goals, and upward-pointing arrows signify increase. The scene is rendered on a white background.', 'uploads/contents/5/preview.jpg', 'uploads/contents/5/preview-watermarked.webp', NULL, 'uploads/contents/5/preview-300.webp', 'uploads/contents/5/preview-600.webp', 'uploads/contents/5/preview-1200.webp', 'uploads/contents/5/author-600.webp', 'png', 0, 'free', 0, 2048, 2048, 'square', NULL, 18, 1, 0, 'exclusive_buyout', 725.00, 1, NULL, 1, '2026-07-30 12:06:31', NULL, '2026-07-30 12:06:31', '2026-07-30 05:55:10', '2026-08-03 06:42:40'),
(6, '698449193727', 1, 4, 106, '3D Business Growth and Success Icons with Trophy for Finance and Leadership', '3d-business-growth-and-success-icons-with-trophy-for-finance-and-leadership', 'Modern 3D business growth and success icons featuring a trophy, financial charts, profit, leadership, achievement, and investment concepts. Ideal for fintech, startups, corporate branding, dashboards, presentations, and marketing designs.', 'uploads/contents/6/preview.jpg', 'uploads/contents/6/preview-watermarked.webp', NULL, 'uploads/contents/6/preview-300.webp', 'uploads/contents/6/preview-600.webp', 'uploads/contents/6/preview-1200.webp', 'uploads/contents/6/author-600.webp', 'png', 0, 'free', 0, 2048, 2048, 'square', NULL, 9, 1, 0, 'exclusive_buyout', 489.00, 1, NULL, 1, '2026-07-30 12:06:15', NULL, '2026-07-30 12:06:15', '2026-07-30 06:00:32', '2026-08-01 12:05:53'),
(7, '842478236718', 1, 4, 106, '3D Business Targeting Icon with Goal Speech Bubble on White Background', '3d-business-targeting-icon-with-goal-speech-bubble-on-white-background', 'Professional 3D business targeting icon featuring a goal speech bubble, target symbol, and communication concept on a white background. Perfect for marketing, business strategy, customer engagement, project planning, presentations, and UI design.', 'uploads/contents/7/preview.jpg', 'uploads/contents/7/preview-watermarked.webp', NULL, 'uploads/contents/7/preview-300.webp', 'uploads/contents/7/preview-600.webp', 'uploads/contents/7/preview-1200.webp', 'uploads/contents/7/author-600.webp', 'png', 0, 'free', 0, 2048, 2048, 'square', NULL, 10, 0, 0, 'exclusive_buyout', 1254.00, 1, NULL, 1, '2026-07-30 12:06:31', NULL, '2026-07-30 12:06:31', '2026-07-30 06:00:50', '2026-08-02 05:10:53'),
(9, '173196470500', 1, 1, 15, 'Cute Cartoon Clock Mascot Character Vector Illustration', 'cute-cartoon-clock-mascot-character-vector-illustration', 'A cute smiling cartoon clock mascot character with a friendly expression and simple flat vector style. Perfect for time management apps, educational materials, children\'s books, stickers, branding, logos, planners, websites, and creative design projects.', 'uploads/contents/9/preview.png', 'uploads/contents/9/preview-watermarked.webp', NULL, 'uploads/contents/9/preview-300.webp', 'uploads/contents/9/preview-600.webp', 'uploads/contents/9/preview-1200.webp', 'uploads/contents/9/author-600.webp', 'vector', 1, 'premium', 0, 1200, 1200, 'square', NULL, 0, 0, 0, 'published', 0.00, 0, NULL, 1, '2026-09-10 17:05:29', NULL, '2026-09-10 17:05:29', '2026-08-02 07:22:55', '2026-09-10 11:05:29'),
(11, '848326559726', 1, 1, 15, 'Cute Superhero Penguin Cartoon Mascot Character Vector Illustration', 'cute-superhero-penguin-cartoon-mascot-character-vector-illustration', 'A cute smiling superhero penguin cartoon mascot wearing a red cape and scarf. Perfect for children\'s books, branding, stickers, logos, educational projects, mobile apps, t-shirts, greeting cards, and creative vector designs.', 'uploads/contents/11/preview.jpg', 'uploads/contents/11/preview-watermarked.webp', NULL, 'uploads/contents/11/preview-300.webp', 'uploads/contents/11/preview-600.webp', 'uploads/contents/11/preview-1200.webp', 'uploads/contents/11/author-600.webp', 'vector', 1, 'premium', 0, 2048, 2048, 'square', NULL, 29, 0, 0, 'published', 0.00, 0, NULL, 1, '2026-08-02 13:38:31', NULL, '2026-08-02 13:38:31', '2026-08-02 07:36:25', '2026-09-09 07:20:42'),
(12, '583058847817', 3, 2, 62, 'High quality vector graphic illustration of Screenshot', 'high-quality-vector-graphic-illustration-of-screenshot', 'High quality vector graphic illustration of Screenshot 92. Isolated design element suitable for banners, posters, social media graphics, web design, print templates, and creative projects. High resolution file included.', 'uploads/contents/12/preview.jpg', 'uploads/contents/12/preview-watermarked.webp', NULL, 'uploads/contents/12/preview-300.webp', 'uploads/contents/12/preview-600.webp', 'uploads/contents/12/preview-1200.webp', 'uploads/contents/12/author-600.webp', 'png', 0, 'free', 0, 517, 526, 'vertical', NULL, 0, 0, 0, 'rejected', 0.00, 0, 'Quality ', 1, '2026-08-02 15:44:17', '', NULL, '2026-08-02 09:42:54', '2026-08-02 09:44:17'),
