INSERT INTO `dynamic_pages` (`id`, `title`, `slug`, `content_format`, `content`, `excerpt`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `og_title`, `og_description`, `og_image`, `status`, `is_indexable`, `sort_order`, `created_by`, `updated_by`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 'About Us', 'about-us', 'html', '<section>\r\n  <p><strong>Welcome to DayalStock</strong></p>\r\n  <p>DayalStock is a modern digital asset marketplace built to help creators, designers, developers, marketers, businesses, and content creators discover high-quality creative resources quickly, securely, and affordably.</p>\r\n  <p>Our mission is to simplify the way digital assets are shared and used by providing a trusted platform where customers can find professional resources and contributors can showcase and monetize their creative work.</p>\r\n  <p>Whether you\'re designing a website, developing a mobile application, creating social media content, producing marketing campaigns, publishing digital products, or building a brand, DayalStock is designed to provide the creative assets you need to bring your ideas to life.</p>\r\n\r\n  <h2>Our Vision</h2>\r\n  <p>Our vision is to become one of the world\'s most trusted digital asset marketplaces by making premium creative resources accessible to everyone while supporting creators through a fair, transparent, and secure ecosystem.</p>\r\n  <p>We believe that great ideas deserve great resources, and every creator should have access to high-quality digital content without unnecessary complexity.</p>\r\n\r\n  <h2>What We Offer</h2>\r\n  <p>DayalStock provides an ever-growing collection of professional digital assets, including:</p>\r\n  <ul>\r\n    <li><strong>Stock Photos</strong></li>\r\n    <li><strong>Premium Vectors</strong></li>\r\n    <li><strong>Illustrations</strong></li>\r\n    <li><strong>PNG Images</strong></li>\r\n    <li><strong>PSD Files</strong></li>\r\n    <li><strong>AI Files</strong></li>\r\n    <li><strong>SVG Files</strong></li>\r\n    <li><strong>Motion Graphics</strong></li>\r\n    <li><strong>Stock Videos</strong></li>\r\n    <li><strong>Icons</strong></li>\r\n    <li><strong>Design Resources</strong></li>\r\n    <li><strong>Additional Creative Assets</strong></li>\r\n  </ul>\r\n  <p>Every asset is carefully categorized and optimized to help users quickly find the content they need.</p>\r\n\r\n  <h2>Why Choose DayalStock?</h2>\r\n  <p>We focus on delivering a simple, reliable, and professional experience.</p>\r\n  <p>Our platform offers:</p>\r\n  <ul>\r\n    <li>High-quality digital assets</li>\r\n    <li>Fast and secure downloads</li>\r\n    <li>Easy search and category navigation</li>\r\n    <li>Affordable pricing and subscription options</li>\r\n    <li>Secure payment processing</li>\r\n    <li>Regularly updated content library</li>\r\n    <li>Reliable customer support</li>\r\n    <li>Fair licensing for personal and commercial projects</li>\r\n    <li>Secure contributor platform</li>\r\n    <li>Continuous platform improvements</li>\r\n  </ul>\r\n\r\n  <h2>Supporting Creative Professionals</h2>\r\n  <p>DayalStock is more than just a marketplace.</p>\r\n  <p>We are building a community where photographers, designers, illustrators, videographers, artists, and creative professionals can publish their work, reach a global audience, protect their intellectual property, and earn from their creativity.</p>\r\n  <p>We are committed to recognizing and respecting the value of original creative work.</p>\r\n\r\n  <h2>Quality Commitment</h2>\r\n  <p>Every effort is made to maintain a high standard of quality across our platform.</p>\r\n  <p>We continuously improve our search system, website performance, security, user experience, and content management process to ensure that customers receive a reliable and enjoyable experience.</p>\r\n\r\n  <h2>Trust, Security &amp; Transparency</h2>\r\n  <p>Your trust is important to us.</p>\r\n  <p>We are committed to protecting user privacy, maintaining secure payment processing, respecting intellectual property rights, and operating our platform with transparency and integrity.</p>\r\n  <p>Our policies, including our Privacy Policy, Terms &amp; Conditions, Refund Policy, License Agreement, and DMCA Policy, are designed to provide a safe and fair experience for both customers and contributors.</p>\r\n\r\n  <h2>Our Future</h2>\r\n  <p>As DayalStock continues to grow, we will expand our collection of digital assets, introduce new features, improve contributor tools, and provide even better services for creative professionals around the world.</p>\r\n  <p>Innovation and continuous improvement remain at the heart of everything we do.</p>\r\n\r\n  <h2>Contact Us</h2>\r\n  <p>We value every customer, contributor, and visitor.</p>\r\n  <p>If you have any questions, feedback, business inquiries, or partnership opportunities, please visit our Contact Us page or contact our support team.</p>\r\n  <p><strong>Email:</strong> <a href=\"mailto:support@dayalstock.com\">support@dayalstock.com</a></p>\r\n\r\n  <p>Thank you for choosing DayalStock.</p>\r\n  <p>We appreciate your trust and look forward to helping you create, design, and build amazing projects with confidence.</p>\r\n</section>', NULL, 'About Us - DayalStock', 'Learn about DayalStock\'s mission, values, and community.', NULL, NULL, NULL, NULL, NULL, 'published', 1, 0, NULL, NULL, '2026-07-19 07:31:30', '2026-07-19 07:31:30', '2026-08-04 10:23:43'),
(2, 'Privacy Policy', 'privacy-policy', 'html', '<p>Welcome to DayalStock. Your privacy is important to us. This Privacy Policy explains how we collect, use, store, share, and protect your personal information when you use our website, services, and digital products.</p>\r\n<p>By accessing or using DayalStock, you agree to the practices described in this Privacy Policy.</p>\r\n\r\n<h2>1. Information We Collect</h2>\r\n<p>We may collect the following types of information:</p>\r\n\r\n<p><strong>Personal Information</strong></p>\r\n<ul>\r\n  <li>Full name</li>\r\n  <li>Email address</li>\r\n  <li>Username</li>\r\n  <li>Profile information</li>\r\n  <li>Billing information (when required)</li>\r\n</ul>\r\n\r\n<p><strong>Account Information</strong></p>\r\n<ul>\r\n  <li>Login details</li>\r\n  <li>Account preferences</li>\r\n  <li>Purchase history</li>\r\n  <li>Download history</li>\r\n</ul>\r\n\r\n<p><strong>Technical Information</strong></p>\r\n<ul>\r\n  <li>IP address</li>\r\n  <li>Browser type and version</li>\r\n  <li>Device information</li>\r\n  <li>Operating system</li>\r\n  <li>Language preferences</li>\r\n  <li>Website usage statistics</li>\r\n</ul>\r\n\r\n<p><strong>Payment Information</strong></p>\r\n<p>Payments are securely processed by trusted third-party payment providers. DayalStock does not store your complete credit card, debit card, or other sensitive payment details on our servers.</p>\r\n\r\n<h2>2. How We Use Your Information</h2>\r\n<p>We use your information to:</p>\r\n<ul>\r\n  <li>Create and manage your account.</li>\r\n  <li>Process payments and orders.</li>\r\n  <li>Provide access to purchased digital assets.</li>\r\n  <li>Improve our website and services.</li>\r\n  <li>Respond to customer support requests.</li>\r\n  <li>Detect fraud and prevent unauthorized activity.</li>\r\n  <li>Send important service-related notifications.</li>\r\n  <li>Comply with legal obligations.</li>\r\n</ul>\r\n\r\n<h2>3. Cookies</h2>\r\n<p>DayalStock uses cookies and similar technologies to:</p>\r\n<ul>\r\n  <li>Keep you logged in.</li>\r\n  <li>Remember your preferences.</li>\r\n  <li>Improve website performance.</li>\r\n  <li>Analyze visitor activity.</li>\r\n  <li>Enhance your browsing experience.</li>\r\n</ul>\r\n<p>You can disable cookies through your browser settings, although some features of the website may not function properly.</p>\r\n\r\n<h2>4. Sharing Your Information</h2>\r\n<p>We do not sell your personal information.</p>\r\n<p>We may share information only with:</p>\r\n<ul>\r\n  <li>Payment providers</li>\r\n  <li>Cloud hosting providers</li>\r\n  <li>Analytics providers</li>\r\n  <li>Legal authorities when required by law</li>\r\n</ul>\r\n\r\n<h2>5. Data Security</h2>\r\n<p>We use reasonable technical and organizational measures to protect your personal information from unauthorized access, loss, misuse, alteration, or disclosure.</p>\r\n<p>However, no online service can guarantee absolute security.</p>\r\n\r\n<h2>6. Data Retention</h2>\r\n<p>We retain your personal information only for as long as necessary to:</p>\r\n<ul>\r\n  <li>Maintain your account</li>\r\n  <li>Process transactions</li>\r\n  <li>Comply with legal obligations</li>\r\n  <li>Resolve disputes</li>\r\n  <li>Enforce our policies</li>\r\n</ul>\r\n\r\n<h2>7. Your Rights</h2>\r\n<p>Depending on applicable laws, you may have the right to:</p>\r\n<ul>\r\n  <li>Access your personal information.</li>\r\n  <li>Update or correct inaccurate information.</li>\r\n  <li>Request deletion of your account and personal data.</li>\r\n  <li>Object to certain processing activities.</li>\r\n  <li>Withdraw consent where applicable.</li>\r\n</ul>\r\n<p>Some information may be retained if required by law or for legitimate business purposes.</p>\r\n\r\n<h2>8. Children\'s Privacy</h2>\r\n<p>DayalStock is not intended for children under the age of 18. We do not knowingly collect personal information from children.</p>\r\n\r\n<h2>9. Third-Party Services</h2>\r\n<p>Our website may contain links to third-party websites or use third-party services, including payment gateways and analytics providers.</p>\r\n<p>We are not responsible for the privacy practices or content of those third-party services.</p>\r\n\r\n<h2>10. International Data Transfers</h2>\r\n<p>Your information may be processed or stored on servers located in different countries. By using DayalStock, you consent to such transfers where permitted by applicable law.</p>\r\n\r\n<h2>11. Policy Updates</h2>\r\n<p>We may update this Privacy Policy from time to time.</p>\r\n<p>Any changes become effective immediately after they are published on this page. We encourage users to review this page periodically.</p>\r\n\r\n<h2>12. Contact Us</h2>\r\n<p>If you have any questions about this Privacy Policy or how your personal information is handled, please contact us through our Contact Us page or email our support team.</p>\r\n<p><strong>Email: </strong><a href=\"mailto:support@dayalstock.com\"><strong>support@dayalstock.com</strong></a></p>\r\n<p>Please also review our Terms &amp; Conditions, Refund Policy, and License Agreement for additional information regarding your use of DayalStock.</p>\r\n<p>By creating an account or using DayalStock, you acknowledge that you have read, understood, and agreed to this Privacy Policy.</p>', NULL, 'Privacy Policy - DayalStock', 'Read our Privacy Policy to understand how DayalStock collects and uses your data.', NULL, NULL, NULL, NULL, NULL, 'published', 1, 0, NULL, NULL, '2026-07-19 07:31:30', '2026-07-19 07:31:30', '2026-08-03 11:01:32'),
(3, 'Terms and Conditions', 'terms-of-use', 'html', '<p>Welcome to DayalStock. These Terms &amp; Conditions (\"Terms\") govern your access to and use of the DayalStock website, services, digital content, and related features. By accessing or using DayalStock, you agree to be bound by these Terms. If you do not agree with any part of these Terms, please do not use our website or services.</p>\r\n\r\n<h2>1. Acceptance of Terms</h2>\r\n<p>By creating an account, browsing, purchasing, downloading, uploading, or otherwise using DayalStock, you acknowledge that you have read, understood, and agreed to these Terms &amp; Conditions, our Privacy Policy, Refund Policy, and License Agreement.</p>\r\n\r\n<h2>2. Eligibility</h2>\r\n<p>You must be at least 18 years old or have the permission of a parent or legal guardian to use DayalStock. You are responsible for ensuring that your use of the platform complies with all applicable laws in your country or region.</p>\r\n\r\n<h2>3. User Accounts</h2>\r\n<p>To access certain features, you may be required to create an account.</p>\r\n<p>You agree to:</p>\r\n<ul>\r\n  <li>Provide accurate and complete information.</li>\r\n  <li>Keep your login credentials secure.</li>\r\n  <li>Be responsible for all activities under your account.</li>\r\n  <li>Notify us immediately if you suspect unauthorized access to your account.</li>\r\n</ul>\r\n<p>DayalStock reserves the right to suspend or terminate any account that violates these Terms.</p>\r\n\r\n<h2>4. Digital Products</h2>\r\n<p>DayalStock provides digital products, including but not limited to:</p>\r\n<ul>\r\n  <li>Stock Photos</li>\r\n  <li>Vectors</li>\r\n  <li>Illustrations</li>\r\n  <li>Videos</li>\r\n  <li>PSD Files</li>\r\n  <li>AI Files</li>\r\n  <li>SVG Files</li>\r\n  <li>Other Creative Assets</li>\r\n</ul>\r\n<p>All products are delivered digitally and are subject to the applicable License Agreement.</p>\r\n\r\n<h2>5. Payments</h2>\r\n<p>All payments must be completed before digital content becomes available for download.</p>\r\n<p>Prices, taxes, and payment methods may change without prior notice.</p>\r\n<p>We reserve the right to refuse or cancel any order suspected of fraud, unauthorized payment, or other illegal activity.</p>\r\n\r\n<h2>6. Downloads and License</h2>\r\n<p>Purchasing or downloading an asset grants you a license to use the content according to our License Agreement.</p>\r\n<p>Purchasing an asset does not transfer ownership or copyright of the content.</p>\r\n<p>You may not:</p>\r\n<ul>\r\n  <li>Resell or redistribute the original files.</li>\r\n  <li>Share downloaded assets with others.</li>\r\n  <li>Claim ownership of any downloaded content.</li>\r\n  <li>Use assets in any unlawful or misleading manner.</li>\r\n</ul>\r\n\r\n<h2>7. Intellectual Property</h2>\r\n<p>All content available on DayalStock, including images, videos, graphics, logos, text, software, and website design, is protected by copyright, trademark, and other intellectual property laws.</p>\r\n<p>Unauthorized copying, distribution, reproduction, or modification is strictly prohibited.</p>\r\n\r\n<h2>8. User Conduct</h2>\r\n<p>You agree not to:</p>\r\n<ul>\r\n  <li>Upload illegal, offensive, harmful, or copyrighted content without authorization.</li>\r\n  <li>Attempt to hack, disrupt, or interfere with the platform.</li>\r\n  <li>Use automated tools, bots, or scripts to abuse our services.</li>\r\n  <li>Engage in fraudulent activities or misuse the platform.</li>\r\n</ul>\r\n<p>Violation of these rules may result in immediate account suspension or permanent termination.</p>\r\n\r\n<h2>9. Account Suspension or Termination</h2>\r\n<p>DayalStock reserves the right to suspend or permanently terminate any account that:</p>\r\n<ul>\r\n  <li>Violates these Terms.</li>\r\n  <li>Engages in fraudulent activity.</li>\r\n  <li>Attempts unauthorized access.</li>\r\n  <li>Abuses refunds or payment systems.</li>\r\n  <li>Infringes intellectual property rights.</li>\r\n</ul>\r\n<p>No refunds will be provided if an account is terminated due to a violation of these Terms.</p>\r\n\r\n<h2>10. Disclaimer of Warranties</h2>\r\n<p>DayalStock provides its website and digital products on an \"as is\" and \"as available\" basis.</p>\r\n<p>We do not guarantee uninterrupted service, error-free operation, or that every asset will meet your specific requirements.</p>\r\n\r\n<h2>11. Limitation of Liability</h2>\r\n<p>To the maximum extent permitted by law, DayalStock shall not be liable for any indirect, incidental, special, consequential, or punitive damages arising from the use of our website or digital products.</p>\r\n<p>Our total liability shall not exceed the amount you paid for the affected purchase.</p>\r\n\r\n<h2>12. Indemnification</h2>\r\n<p>You agree to indemnify and hold harmless DayalStock, its owners, employees, and partners from any claims, damages, liabilities, or expenses arising from your misuse of the platform or violation of these Terms.</p>\r\n\r\n<h2>13. Third-Party Services</h2>\r\n<p>DayalStock may integrate with third-party payment providers or other external services.</p>\r\n<p>We are not responsible for the availability, policies, or actions of any third-party service.</p>\r\n\r\n<h2>14. Changes to These Terms</h2>\r\n<p>We reserve the right to modify or update these Terms &amp; Conditions at any time without prior notice.</p>\r\n<p>Changes become effective immediately upon publication on this page. Continued use of DayalStock after any update constitutes acceptance of the revised Terms.</p>\r\n\r\n<h2>15. Governing Law</h2>\r\n<p>These Terms &amp; Conditions shall be governed and interpreted in accordance with the applicable laws of the jurisdiction in which DayalStock operates, unless otherwise required by applicable law.</p>\r\n\r\n<h2>16. Contact Us</h2>\r\n<p>If you have any questions regarding these Terms &amp; Conditions, please contact us through our Contact Us page or email our support team.</p>\r\n<p><strong>Email: </strong><a href=\"mailto:support@dayalstock.com\"><strong>support@dayalstock.com</strong></a></p>\r\n<p>For additional information, please review our Privacy Policy, Refund Policy, and License Agreement.</p>\r\n<p>By accessing or using DayalStock, you confirm that you have read, understood, and agreed to these Terms &amp; Conditions.</p>', NULL, 'Terms of Use - DayalStock', 'DayalStock\'s Terms and Conditions.', NULL, NULL, NULL, NULL, NULL, 'published', 1, 0, NULL, NULL, '2026-07-19 07:31:30', '2026-07-19 07:31:30', '2026-08-03 10:59:18'),
(4, 'Licensing Agreement', 'licensing', 'json', '{\"intro\":\"DayalStock offers distinct licensing models depending on your subscription status and the asset type.\",\"licenses\":[{\"type\":\"Standard License (Free)\",\"style\":\"free\",\"points\":[{\"label\":\"Attribution\",\"value\":\"[PENDING CONFIRMATION: Is attribution required for free users?]\"},{\"label\":\"Commercial Use\",\"value\":\"[PENDING CONFIRMATION: Allowed or strictly personal?]\"},{\"label\":\"Print Limit\",\"value\":\"[PENDING CONFIRMATION: E.g., Up to 500 copies]\"}]},{\"type\":\"Commercial License (Premium)\",\"style\":\"premium\",\"points\":[{\"label\":\"Attribution\",\"value\":\"[PENDING CONFIRMATION: Not required for premium?]\"},{\"label\":\"Commercial Use\",\"value\":\"[PENDING CONFIRMATION: Full commercial use allowed?]\"},{\"label\":\"Print Limit\",\"value\":\"[PENDING CONFIRMATION: E.g., Up to 500,000 copies or unlimited?]\"}]}],\"permitted\":[\"Web design & Social Media\",\"Print media [PENDING CONFIRMATION: Limits]\",\"Video productions & Broadcasting\",\"[PENDING CONFIRMATION: Other allowed uses]\"],\"prohibited\":[{\"title\":\"Reselling or Redistribution\",\"desc\":\"[PENDING CONFIRMATION: Define exact terms]\"},{\"title\":\"Print-on-Demand (POD)\",\"desc\":\"[PENDING CONFIRMATION: Is using assets on Merch by Amazon allowed?]\"},{\"title\":\"Trademarks & Logos\",\"desc\":\"[PENDING CONFIRMATION: Can an asset be used as a logo?]\"},{\"title\":\"AI Training\",\"desc\":\"[PENDING CONFIRMATION: Is scraping for AI models prohibited?]\"}]}', NULL, 'Licensing - DayalStock', 'DayalStock Licensing rules and agreements.', NULL, NULL, NULL, NULL, NULL, 'published', 1, 0, NULL, NULL, '2026-07-19 07:31:30', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(5, 'Contributor Guidelines & Payout Policy', 'contributor-guidelines', 'json', '{\"intro\":\"To maintain a high standard for our customers, all submitted assets must meet the following criteria:\",\"sections\":[{\"title\":\"Quality & Upload Requirements\",\"content\":\"<ul><li><strong>Image Dimensions:<\\/strong> [PENDING CONFIRMATION: Minimum width\\/height]<\\/li><li><strong>File Formats:<\\/strong> [PENDING CONFIRMATION: E.g., JPG, PNG, EPS]<\\/li><li><strong>Metadata:<\\/strong> [PENDING CONFIRMATION: E.g., Must include an accurate English title]<\\/li><\\/ul>\"},{\"title\":\"Review Process\",\"content\":\"<p>Once you upload an asset, it goes into the pending queue. [PENDING CONFIRMATION: Review process timeline]<\\/p>\"},{\"title\":\"Revenue Share & Earnings\",\"content\":\"<ul><li><strong>Premium Downloads:<\\/strong> [PENDING CONFIRMATION: Revenue share percentage]<\\/li><li><strong>Free Downloads:<\\/strong> [PENDING CONFIRMATION: Do contributors earn from free downloads?]<\\/li><\\/ul>\"},{\"title\":\"Payout Policy\",\"content\":\"<ul><li><strong>Minimum Payout Threshold:<\\/strong> [PENDING CONFIRMATION: E.g., $50 USD]<\\/li><li><strong>Payout Schedule:<\\/strong> [PENDING CONFIRMATION: E.g., Payments are processed on the 15th]<\\/li><li><strong>Supported Payment Methods:<\\/strong> [PENDING CONFIRMATION: E.g., Payoneer, PayPal]<\\/li><\\/ul>\"},{\"title\":\"AI-Generated Content Policy\",\"content\":\"<p>[PENDING CONFIRMATION: Do you accept AI-generated images?]<\\/p>\"},{\"title\":\"Exclusivity\",\"content\":\"<p>[PENDING CONFIRMATION: Are contributors required to upload exclusively to DayalStock?]<\\/p>\"}]}', NULL, 'Contributor Guidelines - DayalStock', 'Learn how to become a contributor at DayalStock.', NULL, NULL, NULL, NULL, NULL, 'published', 1, 0, NULL, NULL, '2026-07-19 07:31:30', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(6, 'DMCA Policy', 'dmca', 'html', '<p>DayalStock respects the intellectual property rights of others and expects all users, contributors, and visitors to do the same. This DMCA &amp; Copyright Policy explains how copyright infringement claims are handled on our platform.</p>\r\n\r\n<h2>1. Copyright Respect</h2>\r\n<p>All content available on DayalStock, including but not limited to stock photos, vectors, illustrations, videos, PSD files, AI files, SVG files, logos, graphics, text, and website design, is protected by applicable copyright and intellectual property laws.</p>\r\n<p>Users may only use downloaded content in accordance with the applicable License Agreement.</p>\r\n\r\n<h2>2. Reporting Copyright Infringement</h2>\r\n<p>If you believe that content available on DayalStock infringes your copyright, you may submit a copyright infringement notice.</p>\r\n<p>Your notice should include:</p>\r\n<ul>\r\n  <li>Your full legal name.</li>\r\n  <li>Your contact email address.</li>\r\n  <li>A description of the copyrighted work.</li>\r\n  <li>The URL or location of the allegedly infringing content.</li>\r\n  <li>A statement that you have a good-faith belief that the use is not authorized by the copyright owner, its agent, or the law.</li>\r\n  <li>A statement that the information provided is accurate and that you are the copyright owner or authorized to act on behalf of the copyright owner.</li>\r\n  <li>Your electronic or physical signature.</li>\r\n</ul>\r\n<p>Incomplete notices may delay the review process.</p>\r\n\r\n<h2>3. DMCA Review Process</h2>\r\n<p>Upon receiving a valid copyright complaint, DayalStock may:</p>\r\n<ul>\r\n  <li>Review the submitted claim.</li>\r\n  <li>Temporarily disable access to the reported content.</li>\r\n  <li>Remove the content if the claim is determined to be valid.</li>\r\n  <li>Notify the contributor or uploader regarding the complaint.</li>\r\n</ul>\r\n<p>We reserve the right to request additional information before making a final decision.</p>\r\n\r\n<h2>4. Counter-Notification</h2>\r\n<p>If you believe that your content was removed by mistake or misidentification, you may submit a counter-notification.</p>\r\n<p>Your counter-notice should include:</p>\r\n<ul>\r\n  <li>Your full legal name.</li>\r\n  <li>Your contact information.</li>\r\n  <li>Identification of the removed content.</li>\r\n  <li>A statement made under penalty of perjury that you believe the content was removed by mistake or misidentification.</li>\r\n  <li>Your electronic or physical signature.</li>\r\n</ul>\r\n<p>After reviewing the counter-notice, DayalStock may restore the content if appropriate and legally permitted.</p>\r\n\r\n<h2>5. Repeat Infringers</h2>\r\n<p>Accounts that repeatedly upload copyrighted content without authorization or repeatedly violate intellectual property rights may be suspended or permanently terminated.</p>\r\n\r\n<h2>6. False Claims</h2>\r\n<p>Submitting false, misleading, or fraudulent copyright complaints or counter-notifications may result in account suspension, legal liability, or other appropriate action.</p>\r\n\r\n<h2>7. Limitation of Responsibility</h2>\r\n<p>DayalStock acts as a platform for digital content distribution. Contributors are responsible for ensuring that the content they upload does not infringe the intellectual property rights of others.</p>\r\n<p>DayalStock is not responsible for user-uploaded content but will respond appropriately to valid copyright complaints.</p>\r\n\r\n<h2>8. Policy Updates</h2>\r\n<p>DayalStock reserves the right to modify or update this DMCA &amp; Copyright Policy at any time. Any changes become effective immediately upon publication on this page.</p>\r\n\r\n<h2>9. Contact Us</h2>\r\n<p>To submit a copyright complaint or DMCA notice, please contact us through our Contact Us page or email:</p>\r\n<p><strong>Email: </strong><a href=\"mailto:copyright@dayalstock.com\"><strong>copyright@dayalstock.com</strong></a></p>\r\n<p>Please include all relevant information to help us process your request as quickly as possible.</p>\r\n<p>By using DayalStock, you acknowledge that you have read, understood, and agreed to this DMCA &amp; Copyright Policy.</p>', NULL, 'DMCA Policy - DayalStock', 'DayalStock DMCA copyright infringement policy.', NULL, NULL, NULL, NULL, NULL, 'published', 1, 0, NULL, NULL, '2026-07-19 07:31:30', '2026-07-19 07:31:30', '2026-08-03 11:05:54'),
(7, 'Contact Us', 'contact-us', 'html', '<section>\r\n  <p><strong>Thank you for visiting DayalStock.</strong></p>\r\n  <p>We value your questions, feedback, and suggestions. Whether you need assistance with your account, purchases, downloads, licensing, copyright matters, or have a business inquiry, our team is here to help.</p>\r\n\r\n  <h2>Customer Support</h2>\r\n  <p>If you need assistance with any of the following, please feel free to contact us:</p>\r\n  <ul>\r\n    <li>Account-related issues</li>\r\n    <li>Login or registration problems</li>\r\n    <li>Payment and billing questions</li>\r\n    <li>Refund requests</li>\r\n    <li>Download or technical issues</li>\r\n    <li>License and copyright inquiries</li>\r\n    <li>Contributor support</li>\r\n    <li>Business partnerships</li>\r\n    <li>General questions and feedback</li>\r\n  </ul>\r\n\r\n  <h2>Contact Information</h2>\r\n  <p><strong>Support Email:</strong> <a href=\"mailto:support@dayalstock.com\">support@dayalstock.com</a><br>\r\n     <strong>Copyright &amp; DMCA:</strong> <a href=\"mailto:copyright@dayalstock.com\">copyright@dayalstock.com</a><br>\r\n     <strong>Website:</strong> <a href=\"https://dayalstock.com\" target=\"_blank\" rel=\"noopener noreferrer\">https://dayalstock.com</a>\r\n  </p>\r\n\r\n  <h2>Response Time</h2>\r\n  <p>Our support team aims to respond to all inquiries as quickly as possible.</p>\r\n  <p>Typical response time:</p>\r\n  <ul>\r\n    <li><strong>General inquiries:</strong> 24–48 business hours</li>\r\n    <li><strong>Billing and payment issues:</strong> 1–3 business days</li>\r\n    <li><strong>Copyright (DMCA) requests:</strong> 3–7 business days</li>\r\n  </ul>\r\n  <p>Response times may vary during weekends, public holidays, or periods of high support volume.</p>\r\n\r\n  <h2>Before Contacting Us</h2>\r\n  <p>To help us resolve your issue faster, please include as much relevant information as possible, such as:</p>\r\n  <ul>\r\n    <li>Your registered email address</li>\r\n    <li>Order ID (if applicable)</li>\r\n    <li>Username</li>\r\n    <li>Description of the issue</li>\r\n    <li>Screenshots or supporting files (if available)</li>\r\n  </ul>\r\n  <p>Providing complete information allows us to investigate your request more efficiently.</p>\r\n\r\n  <h2>Business Inquiries</h2>\r\n  <p>For partnership opportunities, collaborations, licensing discussions, or other business-related matters, please contact us using the support email above and include <strong>\"Business Inquiry\"</strong> in the subject line.</p>\r\n\r\n  <h2>Our Commitment</h2>\r\n  <p>At DayalStock, we are committed to providing reliable support and delivering a positive experience for every customer, contributor, and visitor.</p>\r\n  <p>Your feedback helps us improve our platform and continue building a better marketplace for the creative community.</p>\r\n\r\n  <p>Thank you for choosing DayalStock.</p>\r\n  <p>We look forward to assisting you.</p>\r\n</section>', NULL, 'Contact Us - DayalStock', 'Get in touch with DayalStock.', NULL, NULL, NULL, NULL, NULL, 'published', 1, 0, NULL, NULL, '2026-07-19 07:31:30', '2026-07-19 07:31:30', '2026-08-04 10:28:12'),
(8, 'Refund Policy', 'refund-policy', 'html', '<p>At DayalStock, we provide digital products such as stock photos, vectors, illustrations, PSD files, AI files, SVG files, videos, and other downloadable creative assets. Because these products are delivered instantly and cannot be returned once accessed, our refund policy differs from that of physical products.</p>\r\n\r\n<h2>1. General Policy</h2>\r\n<p>All purchases made through DayalStock are considered final. Once a digital asset has been successfully downloaded or accessed, it is generally not eligible for a refund.</p>\r\n\r\n<h2>2. When You May Be Eligible for a Refund</h2>\r\n<p>A refund request may be approved if any of the following circumstances apply:</p>\r\n<ul>\r\n  <li>Your payment was processed more than once for the same order.</li>\r\n  <li>You were charged, but your order was not completed and no download access was provided.</li>\r\n  <li>The downloaded file is permanently corrupted or technically unusable, and our support team cannot provide a working replacement within a reasonable time.</li>\r\n  <li>You received a file that is significantly different from the product description due to an internal error.</li>\r\n  <li>A billing or payment processing error occurred on our side.</li>\r\n</ul>\r\n\r\n<h2>3. When Refunds Will Not Be Granted</h2>\r\n<p>Refunds will generally not be issued in the following situations:</p>\r\n<ul>\r\n  <li>The digital asset has already been downloaded successfully.</li>\r\n  <li>You purchased the wrong file by mistake.</li>\r\n  <li>You changed your mind after completing the purchase.</li>\r\n  <li>The asset does not meet your personal preferences or project requirements.</li>\r\n  <li>You no longer need the purchased asset.</li>\r\n  <li>You do not have compatible software or hardware to use the file.</li>\r\n  <li>You violated our Terms of Service or License Agreement.</li>\r\n</ul>\r\n\r\n<h2>4. Subscription Refunds</h2>\r\n<p>Subscription fees are generally non-refundable once the subscription period has started.</p>\r\n<p>If you cancel your subscription, it will remain active until the end of your current billing period. No partial or prorated refunds will be provided unless required by applicable law.</p>\r\n\r\n<h2>5. Chargebacks</h2>\r\n<p>If you initiate a payment dispute or chargeback without first contacting our support team, DayalStock reserves the right to temporarily suspend or permanently restrict your account while the dispute is being investigated.</p>\r\n\r\n<h2>6. Refund Request Process</h2>\r\n<p>To request a refund, please get in touch with our support team within 7 days of your purchase.</p>\r\n<p>Please include the following information:</p>\r\n<ul>\r\n  <li>Order ID</li>\r\n  <li>Registered email address</li>\r\n  <li>Payment method</li>\r\n  <li>Reason for the refund request</li>\r\n  <li>Screenshots or other supporting evidence (if applicable)</li>\r\n</ul>\r\n<p>Our team will review your request and typically respond within 3–7 business days.</p>\r\n\r\n<h2>7. Refund Method</h2>\r\n<p>If your refund request is approved, the refund will be issued through the original payment method whenever possible.</p>\r\n<p>Depending on your payment provider, it may take 5–15 business days for the refunded amount to appear in your account.</p>\r\n\r\n<h2>8. Right to Refuse Refund Requests</h2>\r\n<p>DayalStock reserves the right to refuse any refund request if there is evidence of abuse, fraud, misuse of the platform, or violation of our Terms of Service or License Agreement.</p>\r\n\r\n<h2>9. Policy Updates</h2>\r\n<p>DayalStock reserves the right to modify or update this Refund Policy at any time without prior notice. Any changes become effective immediately upon publication on this page. We encourage users to review this page periodically to stay informed of any updates.</p>\r\n\r\n<h2>10. Contact Us</h2>\r\n<p>If you have any questions regarding this Refund Policy or wish to request a refund, please get in touch with us through our Contact Us page or email our support team.</p>\r\n<p>Email: <strong>support@dayalstock.com</strong></p>\r\n<p>For information about how we collect, use, and protect your personal data, please review our Privacy Policy. This Refund Policy should be read together with our Terms of Service and Privacy Policy.</p>\r\n<p>By purchasing, downloading, or accessing any digital content from DayalStock, you acknowledge that you have read, understood, and agreed to this Refund Policy.</p>', NULL, 'Refund Policy - DayalStock', NULL, NULL, NULL, NULL, NULL, NULL, 'published', 1, 0, NULL, NULL, NULL, '2026-08-03 10:30:21', '2026-08-03 11:01:14');
INSERT INTO `dynamic_page_revisions` (`id`, `page_id`, `title`, `content`, `revision_number`, `changed_by`, `created_at`) VALUES
(1, 1, 'About Dayal Stock', '\r\n<p class=\"mb-4\">Welcome to Dayal Stock, the premier destination for high-quality, royalty-free creative assets. Our mission is to empower creators, designers, and businesses by providing world-class photos, videos, and vectors.</p>\r\n<p class=\"mb-4\">Founded with the vision to make professional-grade assets accessible, we have built a thriving community of contributors who share their best work with the world. We believe that great design shouldn\'t be limited by budget or resources.</p>\r\n<h2 class=\"text-2xl font-bold text-gray-900 mt-8 mb-4\">Our Core Values</h2>\r\n<ul class=\"list-disc pl-5 mb-6\">\r\n<li class=\"mb-2\"><strong>Quality:</strong> Every asset is meticulously reviewed to meet our high standards.</li>\r\n<li class=\"mb-2\"><strong>Community:</strong> We support and reward our contributors fairly.</li>\r\n<li class=\"mb-2\"><strong>Innovation:</strong> We continuously improve our platform to make discovering assets effortless.</li>\r\n</ul>', 1, NULL, '2026-07-20 05:43:42'),
(2, 1, 'About Dayal Stock', '\n<p class=\"mb-4\">Welcome to Dayal Stock, the premier destination for high-quality, royalty-free creative assets. Our mission is to empower creators, designers, and businesses by providing world-class photos, videos, and vectors.</p>\n<p class=\"mb-4\">Founded with the vision to make professional-grade assets accessible, we have built a thriving community of contributors who share their best work with the world. We believe that great design shouldn\'t be limited by budget or resources.</p>\n<h2 class=\"text-2xl font-bold text-gray-900 mt-8 mb-4\">Our Core Values</h2>\n<ul class=\"list-disc pl-5 mb-6\">\n<li class=\"mb-2\"><strong>Quality:</strong> Every asset is meticulously reviewed to meet our high standards.</li>\n<li class=\"mb-2\"><strong>Community:</strong> We support and reward our contributors fairly.</li>\n<li class=\"mb-2\"><strong>Innovation:</strong> We continuously improve our platform to make discovering assets effortless.</li><li class=\"mb-2\"><b>Hello: </b>Test Page</li>\n</ul>', 2, NULL, '2026-07-20 05:43:50');
