INSERT INTO `ticket_messages` (`id`, `ticket_id`, `sender_id`, `message`, `attachment_url`, `is_admin_reply`, `is_internal_note`, `created_at`) VALUES
(1, 'TKT-FDB483', 5, 'I have received the notification that my contributor access has been granted and that I am a new contributor. However, I am unable to log in to the contributor portal or access my contributor account.\n\nCould you please check my account and help resolve this issue? If there are any additional steps I need to complete, please let me know.\n\nThank you.', NULL, 0, 0, '2026-07-30 16:51:27'),
(2, 'TKT-F060D3', 4, 'I have already submitted my National ID (NID) for verification, but it has not been approved yet. Could you please review my submission and let me know if any additional information or documents are required? I would appreciate your assistance in resolving this issue as soon as possible.\n\nThank you.', NULL, 0, 0, '2026-07-30 17:02:55'),
(3, 'TKT-FDB483', 1, 'Your contributor access has already been granted. Please wait up to 12 hours, then perform a hard refresh (Ctrl + Shift + R) and try logging in again. If the issue persists after 12 hours, please let us know.', NULL, 1, 0, '2026-07-30 17:06:42'),
(4, 'TKT-F060D3', 1, 'We\'ve already verified your NID. Please do a hard refresh (Ctrl + Shift + R) and check again. If you\'re still seeing the same issue, just let us know and we\'ll help you further.', NULL, 1, 0, '2026-07-30 17:07:51'),
(5, 'TKT-80B76E', 9, 'প্রিয় সাপোর্ট টিম আমি কিছু দিন দরে টাকা তুলতে পারছি না, দয়া করে আমাট এই বিষয় টা সমাধান করে দিবেন।', NULL, 0, 0, '2026-08-04 17:44:08'),
(6, 'TKT-80B76E', 1, 'Bengala not allow', NULL, 1, 0, '2026-08-04 17:44:49'),
(7, 'TKT-80B76E', 9, 'Helli bro', NULL, 0, 0, '2026-08-04 17:48:16');
